def process(cumulative_threshold) -> pd.DataFrame:
    threshold = 6471708 * 0.5
    result_df = cumulative_threshold[cumulative_threshold['Cumulative_Reports'] >= threshold]
    if len(result_df) > 0:
        min_categories = int(result_df.iloc[0]['Rank'])
        return pd.DataFrame({'min_categories': [min_categories]})
    return pd.DataFrame({'min_categories': [len(cumulative_threshold)]})

def process(verify_threshold) -> pd.DataFrame:
    df = verify_threshold.copy()
    df['cumulative_pct'] = (df['Cumulative_Reports'] / 6471708 * 100).round(2)
    return df[['Rank', 'Category', ' # of Reports ', 'Cumulative_Reports', 'cumulative_pct']].head(5)
